// Builds the model call for the provider chosen in Config. The system prompt and JSON schema come
// from prompts/ (mounted read-only): the same files the model comparison in eval/ used.
// formatLead, claudeRequestBody and geminiRequestBody are copied from eval/lib.

const EMPTY = '(not provided)';

const fence = (text) => String(text ?? '').replaceAll('</message>', '</ message>');

function formatLead(input) {
  const header = [`Received at: ${input.received_at}`];
  let body;
  if (input.channel === 'email') {
    header.push('Channel: email');
    body = [`From: ${input.from}`, `Subject: ${input.subject}`, '', input.body];
  } else {
    header.push('Channel: website contact form');
    body = [
      `Name: ${input.name || EMPTY}`,
      `Email: ${input.email || EMPTY}`,
      `Phone: ${input.phone || EMPTY}`,
      `Company: ${input.company || EMPTY}`,
      'Message:',
      input.message,
    ];
  }
  return [...header, '', '<message>', fence(body.join('\n')), '</message>'].join('\n');
}

const MAX_OUTPUT_TOKENS = 8000;

function claudeRequestBody({ model, settings = {}, system, user, schema, maxTokens = MAX_OUTPUT_TOKENS }) {
  const outputConfig = { format: { type: 'json_schema', schema } };
  if (settings.effort) outputConfig.effort = settings.effort;
  return {
    model,
    max_tokens: maxTokens,
    system,
    messages: [{ role: 'user', content: user }],
    output_config: outputConfig,
  };
}

function geminiRequestBody({ settings = {}, system, user, schema, maxTokens = MAX_OUTPUT_TOKENS }) {
  const generationConfig = {
    responseMimeType: 'application/json',
    responseJsonSchema: schema,
    maxOutputTokens: maxTokens,
  };
  if (settings.thinkingLevel) generationConfig.thinkingConfig = { thinkingLevel: settings.thinkingLevel };
  return {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig,
  };
}

let system = null;
let schema = null;
for (const item of $('Read prompt text').all()) {
  try { schema = JSON.parse(item.json.text); } catch { system = item.json.text; }
}
if (!system || !schema) throw new Error('Could not read prompts/lead-intake.system.md and lead-intake.schema.json');

const config = $('Config').first().json;
const lead = $('When called by intake').first().json;
const user = formatLead(lead.input);

// Settings as measured in eval/: Gemini thinking low, Claude effort low.
let request;
if (config.provider === 'gemini') {
  const model = config.gemini_model;
  request = {
    model,
    url: `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,
    body: geminiRequestBody({ settings: { thinkingLevel: 'low' }, system, user, schema }),
  };
} else if (config.provider === 'claude') {
  const model = config.claude_model;
  request = {
    model,
    url: 'https://api.anthropic.com/v1/messages',
    body: claudeRequestBody({ model, settings: { effort: 'low' }, system, user, schema }),
  };
} else {
  throw new Error(`Config: provider must be "gemini" or "claude", got "${config.provider}"`);
}
return [{ json: { provider: config.provider, ...request, schema } }];

// Turns the raw API response into a checked lead record: parses the JSON, validates it against the
// schema, prices the call and picks the route. parseAndValidate and isHot are copied from eval/lib.

function typeOf(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v === 'number' ? 'number' : typeof v;
}

function check(schema, value, path, errors) {
  if (schema.anyOf) {
    const ok = schema.anyOf.some((s) => {
      const sub = [];
      check(s, value, path, sub);
      return sub.length === 0;
    });
    if (!ok) errors.push(`${path}: matches none of the allowed shapes`);
    return;
  }
  const actual = typeOf(value);
  if (schema.type && schema.type !== actual && !(schema.type === 'integer' && Number.isInteger(value))) {
    errors.push(`${path}: expected ${schema.type}, got ${actual}`);
    return;
  }
  if (schema.enum && !schema.enum.includes(value)) errors.push(`${path}: '${value}' is not one of ${schema.enum.join(', ')}`);
  if (actual === 'object') {
    for (const key of schema.required ?? []) if (!(key in value)) errors.push(`${path}.${key}: missing`);
    for (const [key, v] of Object.entries(value)) {
      const sub = schema.properties?.[key];
      if (sub) check(sub, v, `${path}.${key}`, errors);
      else if (schema.additionalProperties === false) errors.push(`${path}.${key}: not allowed`);
    }
  }
  if (actual === 'array' && schema.items) value.forEach((v, i) => check(schema.items, v, `${path}[${i}]`, errors));
}

function parseAndValidate(text, schema) {
  let value;
  try {
    value = JSON.parse(text);
  } catch (e) {
    return { ok: false, value: null, errors: [`not valid JSON: ${e.message}`] };
  }
  const errors = [];
  check(schema, value, '$', errors);
  return { ok: errors.length === 0, value, errors };
}

const HOT_MIN_BUDGET_USD = { one_time: 10000, monthly: 2500 };

function isHot(result) {
  if (result.category !== 'sales_lead' || result.urgency !== 'high') return false;
  const services = result.services ?? [];
  if (services.length > 0 && services.every((s) => s === 'other')) return false;
  const { min, max, currency, period } = result.budget ?? {};
  const amount = max ?? min;
  const threshold = HOT_MIN_BUDGET_USD[period];
  if (currency === 'USD' && amount != null && threshold != null && amount < threshold) return false;
  return true;
}

// USD per million tokens, list prices checked 2026-09-27 (thinking tokens bill as output).
const PRICES = {
  'gemini-3.8-flash': { input: 0.75, output: 3.75 },
  'claude-opus-5-5': { input: 4.0, output: 20.0 },
};

const request = $('Build model request').first().json;
const lead = $('When called by intake').first().json;
const claim = $('Claim lead').first().json;
const response = $input.first().json;

let text = '';
let model = request.model;
let stopReason = 'error';
let usage = { input_tokens: 0, output_tokens: 0 };
let callError = null;

if (response.error) {
  callError = typeof response.error === 'string' ? response.error : (response.error.message ?? JSON.stringify(response.error));
} else if (request.provider === 'claude') {
  text = (response.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  model = response.model ?? model;
  stopReason = response.stop_reason;
  usage = { input_tokens: response.usage?.input_tokens ?? 0, output_tokens: response.usage?.output_tokens ?? 0 };
} else {
  const candidate = response.candidates?.[0];
  text = (candidate?.content?.parts ?? []).filter((p) => !p.thought && typeof p.text === 'string').map((p) => p.text).join('');
  model = response.modelVersion ?? model;
  const finish = candidate?.finishReason ?? response.promptFeedback?.blockReason ?? 'NO_CANDIDATE';
  stopReason = { STOP: 'end_turn', MAX_TOKENS: 'max_tokens', SAFETY: 'refusal' }[finish] ?? finish.toLowerCase();
  const u = response.usageMetadata ?? {};
  usage = { input_tokens: u.promptTokenCount ?? 0, output_tokens: (u.candidatesTokenCount ?? 0) + (u.thoughtsTokenCount ?? 0) };
}
const price = PRICES[request.model];
const costUsd = price ? (usage.input_tokens * price.input + usage.output_tokens * price.output) / 1e6 : null;

// Contact details for the CRM: the model's extraction, falling back to the sender's address.
const checked = callError ? { ok: false, value: null, errors: [callError] } : parseAndValidate(text, request.schema);
const result = checked.ok && stopReason === 'end_turn' ? checked.value : null;
const c = result?.contact ?? {};
const email = String(c.email || lead.reply_to || '').trim().toLowerCase() || null;
const digits = String(c.phone ?? '').replace(/\D/g, '');
const phone = !digits ? null
  : digits.length === 10 ? `+1${digits}`
  : digits.length === 11 && digits.startsWith('1') ? `+${digits}`
  : String(c.phone).trim().startsWith('+') ? `+${digits}` : String(c.phone).trim();
const [firstname, ...rest] = String(c.name ?? '').trim().split(/\s+/).filter(Boolean);

// Route: a bad answer or an unclear message goes to a person instead of failing the workflow.
let route;
let reviewReason = null;
if (!result) {
  route = 'review';
  const why = callError ? 'API call failed' : stopReason !== 'end_turn' ? `stop reason ${stopReason}` : 'answer failed the schema check';
  reviewReason = `AI answer unusable (${why}): ${checked.errors.slice(0, 3).join('; ')}`.slice(0, 500);
} else if (result.category === 'sales_lead' && !email && !phone) {
  route = 'review';
  reviewReason = 'Sales lead without an email address or phone number';
} else if (result.category === 'sales_lead') {
  route = 'lead';
} else if (result.needs_review) {
  route = 'review';
  reviewReason = result.review_reason;
} else {
  route = 'not_a_lead';
}

return [{
  json: {
    lead_id: claim.id,
    claim,
    source: lead.source,
    input: lead.input,
    reply_to: lead.reply_to,
    thread_id: lead.thread_id,
    provider: request.provider,
    model,
    stop_reason: stopReason,
    usage,
    cost_usd: costUsd,
    result,
    is_hot: result ? isHot(result) : false,
    needs_review: !result || !!result.needs_review || route === 'review',
    route,
    review_reason: reviewReason ?? result?.review_reason ?? null,
    contact: { firstname: firstname ?? null, lastname: rest.join(' ') || null, email, phone, company: c.company ?? null },
  },
}];

// A follow-up from someone already in the CRM: attach it to their contact and open deal.
const ctx = $('Check AI answer').first().json;
const known = $input.first().json;
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[ch]);
const i = ctx.input;
const original = i.channel === 'email' ? `Subject: ${i.subject}\n\n${i.body}` : i.message;
const body = [
  `<p><b>Follow-up message.</b> ${esc(ctx.result.summary)}</p>`,
  `<p>${esc(original).replace(/\n/g, '<br>')}</p>`,
  `<p><i>AI Lead Intake · ${esc(ctx.model)} · $${(ctx.cost_usd ?? 0).toFixed(4)}</i></p>`,
].join('');
return [{ json: { contact_id: known.contact_id, deal_id: known.deal_id, body } }];

const ctx = $('Check AI answer').first().json;
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[ch]);
const i = ctx.input;
const sender = i.channel === 'email' ? i.from : [i.name, i.email, i.phone].filter(Boolean).join(' · ');
const text = i.channel === 'email' ? `${i.subject}\n${i.body}` : i.message;
const title = `👀 Needs a look: ${ctx.result?.category?.replace(/_/g, ' ') ?? 'unreadable message'}`;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150) } },
  { type: 'section', text: { type: 'mrkdwn', text: `*Why:* ${esc(ctx.review_reason ?? 'flagged by the model')}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*From:* ${esc(sender)}\n>${esc(text.slice(0, 600)).replace(/\n/g, '\n>')}` } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `${i.channel === 'email' ? 'Email' : 'Website form'} · lead #${ctx.lead_id} · no CRM record or draft created` }] },
];
return [{ json: { text: title, blocks: JSON.stringify({ blocks }) } }];

// Everything the HubSpot calls need, computed once: contact search, contact fields, deal and note.

const ctx = $input.first().json;
const r = ctx.result;
const c = ctx.contact;
const LABELS = { website: 'Website', seo: 'SEO', paid_ads: 'Paid ads', social_media: 'Social media', branding: 'Branding', email_marketing: 'Email marketing', other: 'Not offered' };
const services = r.services.map((s) => LABELS[s] ?? s);

const b = r.budget;
const money = (n) => (b.currency && b.currency !== 'USD' ? `${Number(n).toLocaleString('en-US')} ${b.currency}` : `$${Number(n).toLocaleString('en-US')}`);
let budget = 'not stated';
if (b.period !== 'unknown') {
  if (b.min != null && b.max != null && b.min !== b.max) budget = `${money(b.min)}–${money(b.max)}`;
  else if (b.min == null && b.max != null) budget = `up to ${money(b.max)}`;
  else budget = money(b.max ?? b.min);
  if (b.period === 'monthly') budget += '/month';
}

const name = [c.firstname, c.lastname].filter(Boolean).join(' ');
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[ch]);
const original = ctx.input.channel === 'email' ? `From: ${ctx.input.from}\nSubject: ${ctx.input.subject}\n\n${ctx.input.body}` : ctx.input.message;

const contactProperties = {};
for (const [k, v] of Object.entries({ firstname: c.firstname, lastname: c.lastname, email: c.email, phone: c.phone, company: c.company })) if (v) contactProperties[k] = v;

const filterGroups = [];
if (c.email) filterGroups.push({ filters: [{ propertyName: 'email', operator: 'EQ', value: c.email }] });
if (c.phone) filterGroups.push({ filters: [{ propertyName: 'phone', operator: 'EQ', value: c.phone }] });

const dealProperties = { dealname: `${c.company || name || c.email || c.phone} – ${services.join(', ') || 'New inquiry'}`, pipeline: 'default', dealstage: 'appointmentscheduled' };
if (b.currency === 'USD' && b.period === 'one_time' && (b.max ?? b.min) != null) dealProperties.amount = String(b.max ?? b.min);

const noteBody = [
  `<p><b>${ctx.is_hot ? 'Hot lead. ' : ''}${esc(r.summary)}</b></p><ul>`,
  `<li>Source: ${ctx.source === 'email' ? 'email' : 'website form'}</li>`,
  `<li>Services: ${esc(services.join(', ') || 'not specified')}</li>`,
  `<li>Budget: ${esc(budget)}</li>`,
  `<li>Urgency: ${esc(r.urgency)}</li>`,
  `<li>Language: ${esc(r.language)}</li>`,
  r.needs_review ? `<li>Needs review: ${esc(r.review_reason ?? 'yes')}</li>` : '',
  `</ul><p><b>Original message</b><br>${esc(original).replace(/\n/g, '<br>')}</p>`,
  `<p><i>AI Lead Intake · ${esc(ctx.model)} · $${(ctx.cost_usd ?? 0).toFixed(4)}</i></p>`,
].join('');

return [{ json: { search: { filterGroups, properties: ['email', 'phone', 'firstname', 'lastname', 'company'], limit: 1 }, contactProperties, dealProperties, noteBody, budget, services } }];

// Update the contact the search found (only filling empty fields), or create one. With an email,
// create goes through upsert-by-email, so a contact HubSpot hasn't indexed for search yet is not duplicated.
const crm = $('Prepare CRM records').first().json;
const found = $input.first().json.results?.[0] ?? null;
const base = 'https://api.hubapi.com/crm/v3/objects/contacts';
const props = crm.contactProperties;
let request;
if (found) {
  const current = found.properties ?? {};
  const fill = Object.fromEntries(Object.entries(props).filter(([k]) => !current[k]));
  // HubSpot rejects an empty PATCH; with nothing to add, just read the contact back.
  request = Object.keys(fill).length
    ? { method: 'PATCH', url: `${base}/${found.id}`, body: { properties: fill } }
    : { method: 'POST', url: `${base}/batch/read`, body: { inputs: [{ id: found.id }], properties: ['email'] } };
} else if (props.email) {
  request = { method: 'POST', url: `${base}/batch/upsert`, body: { inputs: [{ idProperty: 'email', id: props.email, properties: { ...props, hs_lead_status: 'NEW' } }] } };
} else {
  request = { method: 'POST', url: base, body: { properties: { ...props, hs_lead_status: 'NEW', lifecyclestage: 'lead' } } };
}
return [{ json: request }];

const ctx = $('Check AI answer').first().json;
const crm = $('Prepare CRM records').first().json;
const r = ctx.result;
const c = ctx.contact;
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[ch]);
const name = [c.firstname, c.lastname].filter(Boolean).join(' ') || 'Unknown sender';
const title = `${ctx.is_hot ? '🔥 Hot lead' : '👀 Lead to review'}: ${c.company || name}`;
const deal = $('Remember deal').isExecuted ? $('Remember deal').first().json.deal_id : $('Remember contact').first().json.deal_id;
const draft = $('Create Gmail draft').isExecuted || ctx.claim.gmail_draft_id ? 'draft reply saved in Gmail' : 'no draft (no email address)';
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150) } },
  { type: 'section', text: { type: 'mrkdwn', text: esc(r.summary) } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Contact*\n${esc(name)}${c.company ? `, ${esc(c.company)}` : ''}` },
    { type: 'mrkdwn', text: `*Reach at*\n${esc([c.email, c.phone].filter(Boolean).join('\n') || '—')}` },
    { type: 'mrkdwn', text: `*Services*\n${esc(crm.services.join(', ') || '—')}` },
    { type: 'mrkdwn', text: `*Budget · urgency*\n${esc(crm.budget)} · ${esc(r.urgency)}` },
  ] },
];
if (ctx.needs_review && ctx.review_reason) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Why review:* ${esc(ctx.review_reason)}` } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `${ctx.source === 'email' ? 'Email' : 'Website form'} · HubSpot deal ${deal} · ${draft}` }] });
return [{ json: { text: title, blocks: JSON.stringify({ blocks }) } }];
